#!/usr/bin/env bash
# clinic/scripts/register-connectors.sh against a fake Kafka Connect (a curl on
# PATH that records each PUT body):
#   - each config's ${...} passwords are filled in from clinic/.env, and only the
#     "config" object is sent: no "name", no generated-file "//" note;
#   - the generated file on disk keeps its placeholder, and nothing filled in is
#     written anywhere else (no stray file under /tmp);
#   - a config whose password .env lacks is not uploaded, and the run fails;
#   - Connect's reply echoes the config, password included: on a non-2xx reply
#     the run fails and the password is masked, including one with a
#     JSON-escaped quote and backslash (a naive [^"]* value pattern stops at the
#     embedded \" and leaks the rest);
#   - a curl that crashes mid-run stops the run with a nonzero exit and leaks
#     nothing.
set -u
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO="$(cd "${HERE}/../../.." && pwd)"
REG="${REPO}/clinic/scripts/register-connectors.sh"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fails=0
assert_rc(){ if [ "$2" -eq "$3" ]; then printf '  ok   %s\n' "$1"; else printf '  FAIL %s: rc %s want %s\n' "$1" "$2" "$3"; fails=$((fails+1)); fi; }
assert_nz(){ if [ "$2" -ne 0 ]; then printf '  ok   %s\n' "$1"; else printf '  FAIL %s: rc 0, want nonzero\n' "$1"; fails=$((fails+1)); fi; }
assert_eq(){ if [ "$2" = "$3" ]; then printf '  ok   %s\n' "$1"; else printf '  FAIL %s: got %q want %q\n' "$1" "$2" "$3"; fails=$((fails+1)); fi; }
assert_not_contains(){ if printf '%s' "$2" | grep -q -- "$3"; then printf '  FAIL %s: output contains %q\n' "$1" "$3"; fails=$((fails+1)); else printf '  ok   %s\n' "$1"; fi; }

# Fixture: a clinic directory with .env, and generated configs in their own directory.
C="$TMP/clinic"; D="$C/connectors"; mkdir -p "$C" "$D" "$TMP/sent" "$TMP/bin"
printf 'LOCAL_DEBEZIUM_PASSWORD=SRC_PW_1\nODOO_DB_PASSWORD=ODOO_PW_2\n' > "$C/.env"
gen(){ # NAME PASSWORD-PLACEHOLDER
  printf '{"//":"Generated by clinic/scripts/generate-connectors.sh","name":"%s","config":{"connector.class":"io.debezium.connector.mysql.MySqlConnector","database.password":"${%s}","topic.prefix":"bahmni-t"}}\n' "$1" "$2" > "$D/$1.json"
}
gen conn-ok LOCAL_DEBEZIUM_PASSWORD
gen conn-two ODOO_DB_PASSWORD
gen conn-nopw CLINLIMS_SOURCE_PASSWORD
gen conn-bad ODOO_DB_PASSWORD
gen conn-badmask ODOO_DB_PASSWORD

# Fake curl. A PUT records its body under $FAKE_DIR and answers per connector:
# conn-bad crashes (curl itself exits nonzero), conn-badmask answers 500 with a
# password holding an escaped quote and backslash, the rest answer 201 echoing a
# password. GET /connectors answers (reachable); GET /connectors/<name> is 404.
cat > "$TMP/bin/curl" <<'EOF'
#!/usr/bin/env bash
last=""; put=0
for a in "$@"; do last="$a"; [ "$a" = PUT ] && put=1; done
if [ "$put" = 1 ]; then
  n="${last%/config}"; n="${n##*/}"
  cat > "$FAKE_DIR/$n.body"
  case "$n" in
    conn-bad) printf '{"name":"conn-bad","config":{"connection.password":"SECRET_VALUE_XYZ"}}\n500'; exit 1 ;;
    conn-badmask) printf '%s\n%s' '{"name":"conn-badmask","config":{"connection.password":"SEC\"RET\\VAL"}}' '500'; exit 0 ;;
    *) printf '{"name":"%s","config":{"connection.password":"SECRET_VALUE_XYZ"}}\n201' "$n"; exit 0 ;;
  esac
fi
case "$last" in
  */connectors) printf '[]' ;;
  *) exit 22 ;;
esac
EOF
chmod +x "$TMP/bin/curl"
reg(){ env PATH="$TMP/bin:$PATH" FAKE_DIR="$TMP/sent" CLINIC_DIR="$C" CONNECT_URL="http://fake-connect:8083" bash "$REG" "$@" 2>&1; }

# --- a good upload ---------------------------------------------------------------
before_tmp="$(ls -a /tmp 2>/dev/null | sort)"
before_d="$(cat "$D"/*.json | cksum)"
out="$(reg conn-ok conn-two)"; rc=$?
assert_rc "two configs with their passwords in .env register" "$rc" 0
body="$(cat "$TMP/sent/conn-ok.body" 2>/dev/null)"
assert_eq "the password is filled in from .env" "$(printf '%s' "$body" | python3 -c 'import json,sys; print(json.load(sys.stdin)["database.password"])' 2>&1)" "SRC_PW_1"
assert_eq "only the config object is sent (no name, no // note)" "$(printf '%s' "$body" | python3 -c 'import json,sys; d=json.load(sys.stdin); print(sorted(d))' 2>&1)" "['connector.class', 'database.password', 'topic.prefix']"
assert_eq "each config gets its own password" "$(python3 -c 'import json,sys; print(json.load(open(sys.argv[1]))["database.password"])' "$TMP/sent/conn-two.body" 2>&1)" "ODOO_PW_2"
assert_eq "the generated files on disk keep their placeholders" "$(cat "$D"/*.json | cksum)" "$before_d"
assert_eq "no stray file left under /tmp" "$(ls -a /tmp 2>/dev/null | sort)" "$before_tmp"
assert_not_contains "the echoed password never reaches the output" "$out" "SECRET_VALUE_XYZ"
assert_not_contains "nor the filled-in one" "$out" "SRC_PW_1"

# --- a password .env lacks --------------------------------------------------------
rm -f "$TMP/sent"/*
out="$(reg conn-nopw)"; rc=$?
assert_nz "a config whose password .env lacks fails the run" "$rc"
assert_rc "and is never sent" "$([ -e "$TMP/sent/conn-nopw.body" ]; echo $?)" 1

# --- a crash on the second connector ------------------------------------------------
before_tmp="$(ls -a /tmp 2>/dev/null | sort)"
out="$(reg conn-ok conn-bad)"; rc=$?
assert_nz "a hard curl failure on the second connector is a nonzero exit" "$rc"
assert_rc "/tmp/.reg.out does not exist afterwards" "$([ -e /tmp/.reg.out ]; echo $?)" 1
assert_eq "no stray file left under /tmp" "$(ls -a /tmp 2>/dev/null | sort)" "$before_tmp"
assert_not_contains "the echoed password never reaches the output" "$out" "SECRET_VALUE_XYZ"
assert_not_contains "nor the filled-in one" "$out" "ODOO_PW_2"

# --- a non-2xx reply ---------------------------------------------------------------
out="$(reg conn-badmask)"; rc=$?
assert_nz "a non-2xx reply (curl exits 0) fails the run" "$rc"
assert_not_contains "an escaped-quote password does not leak its prefix (SEC)" "$out" "SEC"
assert_not_contains "an escaped-quote password does not leak its middle (RET)" "$out" "RET"
assert_not_contains "an escaped-quote password does not leak its suffix (VAL)" "$out" "VAL"

exit "$fails"
